-module(membership_setup).
-export([page/1,data/3,action/5,webhook/4,signature/3]).
query(Db,Sql,Params)->Q=lists:foldl(fun(V,A)->pog:parameter(A,pog_ffi:coerce(V)) end,pog:'query'(Sql),Params),pog:execute(pog:returning(Q,gleam@dynamic@decode:at([0],{decoder,fun gleam@dynamic@decode:decode_string/1})),Db).
value(Db,Sql,P)->case query(Db,Sql,P) of {ok,R}->case element(3,R) of [V|_]->V;_-> <<>> end;_-> <<>> end.
reply(V)->case V of <<>>->wisp:response(503);_->wisp:json_body(wisp:ok(),V) end.
form(F,K)->proplists:get_value(K,F,<<>>).
data(Db,T,U)->reply(value(Db,<<"select agency.membership_setup_data($1::uuid,$2::uuid)::text">>,[T,U])).
action(Db,T,U,<<"test">>,F)->reply(value(Db,<<"select jsonb_build_object('status',agency.membership_connection_test($1::uuid,$2::uuid,$3,$4))::text">>,[T,U,form(F,<<"channel">>),form(F,<<"target">>)]));
action(Db,T,_U,<<"smtp">>,F)->
 Host=form(F,<<"host">>),User=form(F,<<"username">>),Pass=form(F,<<"smtp_password">>),From=form(F,<<"from">>),Port=form(F,<<"port">>),
 case re:run(Host,<<"^[a-zA-Z0-9.-]{1,253}$">>,[{capture,none}])=:=match andalso byte_size(User)>0 andalso byte_size(User)=<254 andalso byte_size(Pass)>0 andalso byte_size(Pass)=<1024 andalso re:run(From,<<"^[^\\s<>@]+@[^\\s<>@]+\\.[^\\s<>@]+$">>,[{capture,none}])=:=match andalso lists:member(Port,[<<"587">>,<<"465">>,<<"25">>]) of
 false->wisp:json_body(wisp:response(422),<<"{\"status\":\"invalid\"}">>);
 true->{ok,Sealed}=nexus_agency@secrets:seal_for_tenant(T,<<"settings.smtp_password">>,Pass),reply(value(Db,<<"with saved as (insert into agency.settings(tenant_id,key,value) values($1::uuid,'smtp_host',to_jsonb($2::text)),($1::uuid,'smtp_username',to_jsonb($3::text)),($1::uuid,'smtp_password_sealed',to_jsonb($4::text)),($1::uuid,'smtp_from',to_jsonb($5::text)),($1::uuid,'smtp_port',to_jsonb($6::text::int)) on conflict(tenant_id,key) do update set value=excluded.value returning key), cleaned as (delete from agency.settings where tenant_id=$1::uuid and key='smtp_password') select jsonb_build_object('status','saved','count',count(*))::text from saved">>,[T,Host,User,Sealed,From,Port])) end;
action(Db,T,_U,<<"webhook">>,F)->
 A=form(F,<<"app_secret">>),V=form(F,<<"verify_token">>),
 case byte_size(A)>=16 andalso byte_size(A)=<256 andalso byte_size(V)>=16 andalso byte_size(V)=<256 of
 false->wisp:json_body(wisp:response(422),<<"{\"status\":\"invalid\"}">>);
 true->{ok,SA}=nexus_agency@secrets:seal_for_tenant(T,<<"membership.whatsapp.app_secret">>,A),{ok,SV}=nexus_agency@secrets:seal_for_tenant(T,<<"membership.whatsapp.verify_token">>,V),
 reply(value(Db,<<"with saved as (insert into agency.settings(tenant_id,key,value) values($1::uuid,'membership_whatsapp_app_secret_sealed',to_jsonb($2::text)),($1::uuid,'membership_whatsapp_verify_token_sealed',to_jsonb($3::text)) on conflict(tenant_id,key) do update set value=excluded.value returning key) select jsonb_build_object('status','saved','count',count(*))::text from saved">>,[T,SA,SV])) end;
action(_,_,_,_,_)->wisp:response(404).
secret(Db,T,Key,Context)->Sealed=value(Db,<<"select value#>>'{}' from agency.settings where tenant_id=$1::uuid and key=$2">>,[T,Key]),nexus_agency@secrets:open_for_tenant(T,Context,Sealed).
signature(Secret,Body,<<"sha256=",Hex/binary>>)->try crypto:hash_equals(crypto:mac(hmac,sha256,Secret,Body),binary:decode_hex(Hex)) catch _:_ ->false end;
signature(_,_,_)->false.
webhook(Req,Db,T,get)->case secret(Db,T,<<"membership_whatsapp_verify_token_sealed">>,<<"membership.whatsapp.verify_token">>) of
 {ok,Secret}->case gleam@http@request:get_query(Req) of {ok,P}->Token=form(P,<<"hub.verify_token">>),C=form(P,<<"hub.challenge">>),case form(P,<<"hub.mode">>)=:= <<"subscribe">> andalso C=/= <<>> andalso crypto:hash_equals(crypto:hash(sha256,Secret),crypto:hash(sha256,Token)) of true->wisp:string_body(wisp:ok(),C);false->wisp:response(403) end;_->wisp:response(400) end;
 _->wisp:response(503) end;
webhook(Req,Db,T,post)->case {secret(Db,T,<<"membership_whatsapp_app_secret_sealed">>,<<"membership.whatsapp.app_secret">>),gleam@http@request:get_header(Req,<<"x-hub-signature-256">>)} of
 {{ok,Secret},{ok,Sig}}->wisp:require_bit_array_body(Req,fun(Body)->case byte_size(Body)=<262144 andalso signature(Secret,Body,Sig) of false->wisp:response(401);true->try
 P=json:decode(Body),true=maps:get(<<"object">>,P)=:= <<"whatsapp_business_account">>,
 Results=[value(Db,<<"select agency.customer_phone_delivery($1::uuid,$2,$3,$4)::text">>,[T,maps:get(<<"phone_number_id">>,maps:get(<<"metadata">>,Value,#{}),<<>>),maps:get(<<"id">>,Status,<<>>),maps:get(<<"status">>,Status,<<>>)]) || E<-maps:get(<<"entry">>,P,[]),C<-maps:get(<<"changes">>,E,[]),Value<-[maps:get(<<"value">>,C,#{})],Status<-maps:get(<<"statuses">>,Value,[])],
 case lists:member(<<>>,Results) of true->wisp:response(503);false->wisp:string_body(wisp:ok(),<<"ok">>) end
 catch _:_ ->wisp:response(400) end end end);
 _->wisp:response(401) end.
page(Csrf)->
 Html= <<"<!doctype html><html lang='tr'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='csrf-token' content='{{csrf}}'><title>Üyelik kurulumu</title><link rel='stylesheet' href='/static/customer-verification.css'><link rel='stylesheet' href='/static/membership-setup.css'></head><body><main class='cv-wrap'><nav><a href='/admin'>Yönetim paneli</a> · <a href='/admin/settings'>Ayarlar</a> · <a href='/admin/integrations'>Entegrasyonlar</a></nav><h1>Üyelik kurulumu ve bildirimler</h1><p>Bağlantıları kontrol edin, test gönderin ve bekleyen işlemleri takip edin.</p><section class='cv-card'><h2>Kurulum kontrolü</h2><p>Hazır durumu, ayarların dolu olduğunu gösterir. Gerçek bağlantıyı test gönderimiyle kontrol edin.</p><div id='setup-checklist' aria-live='polite'></div><button type='button' id='setup-refresh'>Durumu yenile</button></section><section class='cv-card'><h2>E-posta bağlantısını düzenle</h2><form id='setup-smtp'><label>SMTP sunucusu<input name='host' maxlength='253' required placeholder='smtp.example.com'></label><label>SMTP kullanıcı adı<input name='username' maxlength='254' required autocomplete='off'></label><label>SMTP parolası<input name='smtp_password' type='password' required maxlength='1024' autocomplete='new-password'></label><label>Gönderen e-posta adresi<input name='from' type='email' maxlength='254' required></label><label>SMTP portu<select name='port'><option value='587'>587 — STARTTLS</option><option value='465'>465 — TLS</option></select></label><label>Mevcut yönetici parolası<input name='password' type='password' autocomplete='current-password' required></label><label>İki aşamalı giriş kodu (etkinse)<input name='mfa_code' maxlength='16' autocomplete='one-time-code'></label><button>E-posta bağlantısını kaydet</button><p role='status'></p></form></section><section class='cv-card'><h2>Bağlantı testi</h2><p>E-posta testi kendi yönetici adresinize gider. WhatsApp testini yalnız kendi veya izin veren bir test numarasına gönderin; bu test kimlik onayı yapmaz.</p><form id='setup-test'><label>Kanal<select name='channel'><option value='email'>E-posta</option><option value='whatsapp'>WhatsApp</option></select></label><label>Test alıcısı<input name='target' required maxlength='254' autocomplete='off'></label><label>Mevcut yönetici parolası<input name='password' type='password' autocomplete='current-password' required></label><label>İki aşamalı giriş kodu (etkinse)<input name='mfa_code' autocomplete='one-time-code' maxlength='16'></label><button>Test gönder</button><p role='status'></p></form><div id='setup-tests'></div></section><section class='cv-card'><h2>WhatsApp teslim takibi</h2><p>Meta panelindeki callback URL alanına aşağıdaki adresi girin ve messages webhook alanına abone olun. Lokal adres Meta tarafından erişilemez; canlı HTTPS adresi gerekir.</p><code id='setup-callback'></code><p><a href='https://whatsapp.github.io/WhatsApp-Nodejs-SDK/api-reference/webhooks/start/' target='_blank' rel='noopener noreferrer'>Meta webhook doğrulama açıklaması</a></p><form id='setup-webhook'><label>Meta uygulama gizli anahtarı (App Secret)<input name='app_secret' type='password' minlength='16' maxlength='256' autocomplete='new-password' required></label><label>Webhook doğrulama belirteci<input name='verify_token' type='password' minlength='16' maxlength='256' autocomplete='new-password' required></label><p>En az 16 karakterlik bir belirteç belirleyin; aynı değeri Meta paneline girin. Anahtarlar şifrelenir ve tekrar gösterilmez.</p><label>Mevcut yönetici parolası<input name='password' type='password' autocomplete='current-password' required></label><label>İki aşamalı giriş kodu (etkinse)<input name='mfa_code' autocomplete='one-time-code' maxlength='16'></label><button>Webhook bağlantısını kaydet</button><p role='status'></p></form></section><section class='cv-card' id='setup-alerts'><h2>Bildirim merkezi</h2><div id='setup-notifications' aria-live='polite'></div><p><a href='/admin/customer-verification'>Kimlik başvurularını incele</a> · <a href='/admin/notifications'>E-posta bildirimleri</a></p></section><p>Üyelik sistemi NEXUS bağlantısı olmadan çalışır. KPS yetkisi gelene kadar kimlik incelemesi manuel devam eder.</p></main><script src='/static/membership-setup.js' defer></script></body></html>"/utf8>>,
 wisp:html_body(wisp:ok(),binary:replace(Html,<<"{{csrf}}">>,Csrf,[global])).
